#!/usr/bin/env python3
"""Verify corpus reports consumed exactly the hash-pinned official WAST files."""
import argparse
import json
import os
from pathlib import Path


MODES = ("originals-only", "fixed-mutations")
ORIGINALS_ONLY_SKIP_REASON = (
    "originals-only mode does not construct or audit generated byte variants"
)


def corpus_mode(value: str | None = None) -> str:
    mode = value if value is not None else os.environ.get("UWGIT_CORPUS_MODE", "fixed-mutations")
    if mode not in MODES:
        raise ValueError(f"unknown UWGIT_CORPUS_MODE {mode!r}; expected {' or '.join(MODES)}")
    return mode


def verify(inputs: Path, evidence: Path, mode: str | None = None) -> dict:
    mode = corpus_mode(mode)
    data = json.loads(inputs.read_text())
    summaries = []
    for corpus in data["corpora"]:
        report_path = evidence / f'spec-core{corpus["version"]}.json'
        report = json.loads(report_path.read_text())
        # Old reports without mode fields came from the fixed-mutation runner.
        # They are never accepted as evidence of an originals-only execution.
        reported_mode = report.get("corpus_mode", "fixed-mutations")
        if reported_mode not in MODES:
            raise ValueError(f'unknown reported corpus mode for {corpus["tag"]}: {reported_mode!r}')
        if reported_mode != mode:
            raise ValueError(f'corpus mode mismatch for {corpus["tag"]}: {reported_mode} != {mode}')
        expected = {item["path"]: item["sha256"] for item in corpus["files"]}
        actual = {item["path"]: item["sha256"] for item in report["files"]}
        if len(actual) != len(report["files"]) or actual != expected:
            raise ValueError(f'corpus source manifest mismatch for {corpus["tag"]}')
        if report["failures"] or report["excluded_symlinks"]:
            raise ValueError(f'corpus audit failures/exclusions for {corpus["tag"]}')
        if report["encoding_counts"].get("component_model_excluded", 0):
            raise ValueError(f'unexpected component exclusions in Core corpus {corpus["tag"]}')
        modules = [module for file in report["files"] for module in file["modules"]]
        encoded = [module for module in modules if module["audit_validation"] is not None]
        if any(module["identity_checked"] is not True for module in encoded):
            raise ValueError(f'missing original identity evidence for {corpus["tag"]}')
        if any(module["patch_identity_replayed"] is not True for module in encoded):
            raise ValueError(f'missing original serialized patch replay evidence for {corpus["tag"]}')
        generated = sum(module["mutation_offset"] is not None for module in modules)
        declared_generated = report.get("generated_mutations", generated)
        if type(declared_generated) is not int or declared_generated != generated:
            raise ValueError(f'generated mutation count differs from module evidence for {corpus["tag"]}')
        if mode == "originals-only":
            if "generated_mutations" not in report or declared_generated != 0:
                raise ValueError(f'originals-only report generated mutation variants for {corpus["tag"]}')
            for module in modules:
                if (module["mutation_offset"] is not None
                    or module["mutation_replayed"] is not False
                    or module["patch_mutation_replayed"] is not False
                    or module.get("mutation_skip_reason") != ORIGINALS_ONLY_SKIP_REASON):
                    raise ValueError(f'originals-only module has generated mutation evidence or no skip reason for {corpus["tag"]}')
        else:
            if generated != len(encoded):
                raise ValueError(f'missing fixed mutation variant for {corpus["tag"]}')
            if any(module.get("mutation_skip_reason") is not None for module in modules):
                raise ValueError(f'fixed-mutations report unexpectedly skips mutation work for {corpus["tag"]}')
            for module in modules:
                if module["audit_validation"] is None:
                    if (module["mutation_offset"] is not None
                        or module["mutation_replayed"] is not False
                        or module["patch_mutation_replayed"] is not False):
                        raise ValueError(f'unaudited module has generated mutation evidence for {corpus["tag"]}')
                else:
                    length = module["byte_len"]
                    position = 8 + (length - 8) // 2 if length > 8 else length
                    if type(module["mutation_offset"]) is not int or module["mutation_offset"] != position:
                        raise ValueError(f'fixed mutation offset does not match the original length for {corpus["tag"]}')
            if any(module["mutation_replayed"] is not True for module in encoded):
                raise ValueError(f'missing mutation replay evidence for {corpus["tag"]}')
            if any(module["patch_mutation_replayed"] is not True for module in encoded):
                raise ValueError(f'missing serialized mutation patch evidence for {corpus["tag"]}')
        profile_counts = {}
        feature_status_counts = {}
        for module in encoded:
            profiles = module.get("standard_profiles", [])
            if {profile["standard"] for profile in profiles} != {"core1", "core2", "core3"} or len(profiles) != 3:
                raise ValueError(f'missing/duplicate cross-standard evidence for {corpus["tag"]}')
            if len({profile["physical_topology_sha256"] for profile in profiles}) != 1:
                raise ValueError(f'cross-standard decoding boundaries differ for {corpus["tag"]}')
            for profile in profiles:
                if (profile["reported_validation"] == "valid") != (profile["validator_valid"] and profile["requirements_satisfied"]):
                    raise ValueError(f'cross-standard validation differs for {corpus["tag"]}')
                key = profile["standard"] + ":" + profile["reported_validation"]
                profile_counts[key] = profile_counts.get(key, 0) + 1
                for feature, value in profile["feature_status_counts"].items():
                    key = profile["standard"] + ":" + feature
                    feature_status_counts[key] = feature_status_counts.get(key, 0) + value
        summaries.append({
            "version": corpus["version"], "tag": corpus["tag"], "commit": corpus["commit"],
            "archive_sha256": corpus["archive_sha256"], "files": len(actual),
            "modules": len(modules), "auditable_binary_modules": len(encoded),
            "corpus_mode": reported_mode, "generated_mutations": generated,
            "mutation_replay_modules": sum(module["mutation_replayed"] is True for module in modules),
            "patch_identity_modules": len(encoded),
            "patch_mutation_modules": sum(module["patch_mutation_replayed"] is True for module in modules),
            "mutation_skipped_modules": sum(module.get("mutation_skip_reason") is not None for module in modules),
            "cross_standard_inspections": len(encoded) * 3,
            "standard_profile_outcomes": profile_counts,
            "feature_status_counts": feature_status_counts,
            "outcomes": report["outcome_counts"],
            "known_profile_limitations": report.get("known_profile_limitations", []),
            "runtime_conformance_tested": report["runtime_conformance_tested"],
            "source_manifest_sha256": report["source_manifest_sha256"],
        })
    return {"format": 1, "verified": True, "corpus_mode": mode, "corpora": summaries}


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("inputs", type=Path)
    parser.add_argument("evidence", type=Path)
    parser.add_argument("--corpus-mode", choices=MODES,
                        help="expected report mode; defaults to UWGIT_CORPUS_MODE or fixed-mutations")
    args = parser.parse_args()
    print(json.dumps(verify(args.inputs, args.evidence, args.corpus_mode), indent=2))
